package com.cyledger.android;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Runs in a private maintenance process, so SQLite is closed before swapping. */
public final class MaintenanceActivity extends Activity {
 static void removeTree(File file){if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)removeTree(child);}file.delete();}
 static void recover(File files)throws Exception{File journal=new File(files,"restore-journal.json");if(!journal.isFile())return;JSONObject data=new JSONObject(new String(java.nio.file.Files.readAllBytes(journal.toPath()),StandardCharsets.UTF_8));File ledger=new File(files,"ledger"),old=new File(files,data.getString("old"));if(!old.getCanonicalFile().getParentFile().equals(files.getCanonicalFile())||!old.getName().startsWith("restore-previous-"))throw new Exception();if(!ledger.exists()&&old.exists()&&!old.renameTo(ledger))throw new Exception();journal.delete();}
 @Override public void onCreate(Bundle state){super.onCreate(state);TextView message=new TextView(this);message.setText("正在恢复账本，请稍候…");message.setTextSize(20);message.setGravity(17);setContentView(message);new Thread(()->{try{File files=getFilesDir(),stage=new File(getIntent().getStringExtra("stage"));if(!stage.getCanonicalFile().getParentFile().equals(files.getCanonicalFile())||!stage.getName().startsWith("restore-")||!new File(stage,"data/cyledger.db").isFile())throw new Exception();int pid=getIntent().getIntExtra("pid",0);if(pid<=0||pid==android.os.Process.myPid())throw new Exception();android.os.Process.killProcess(pid);for(int i=0;i<100&&new File("/proc/"+pid).exists();i++)Thread.sleep(50);if(new File("/proc/"+pid).exists())throw new Exception();File ledger=new File(files,"ledger"),old=new File(files,"restore-previous-"+System.currentTimeMillis()),journal=new File(files,"restore-journal.json");try(FileOutputStream out=new FileOutputStream(journal)){out.write(new JSONObject().put("old",old.getName()).toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!ledger.renameTo(old))throw new Exception();if(!stage.renameTo(ledger)){old.renameTo(ledger);throw new Exception();}journal.delete();runOnUiThread(()->{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();android.os.Process.killProcess(android.os.Process.myPid());});}catch(Exception e){try{recover(getFilesDir());}catch(Exception ignored){}runOnUiThread(()->new AlertDialog.Builder(this).setTitle("恢复未完成").setMessage("已保留恢复前的账本，请重新打开应用。").setPositiveButton("重新打开",(d,w)->{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();}).setCancelable(false).show());}},"CYLedger-restore").start();}
}
